using System;using System.Linq;using System.Collections.Generic;using System.Globalization;using System.Windows.Forms;
namespace BeamScheduleFormatter {
class TimberTakeoff {public string Kind,Id;public double Length,Thickness,Width,StockFeet;public int Pieces;public SteelCutDemand Demand;public double Net{get{return Thickness*Width*(Length/.3048)/12*Pieces;}}}
static class TimberQuantities {
 public static TimberTakeoff Create(string kind,string id,string description,double length,double thicknessInches,double widthInches,int pieces,double stockFeet,string specification){SteelWeight.Positive(length,thicknessInches,widthInches,stockFeet);SteelWeight.Count(pieces);if(string.IsNullOrWhiteSpace(id)||string.IsNullOrWhiteSpace(specification)||length>stockFeet*.3048+1e-9)throw new Exception("Enter member ID/specification and a cut that fits the selected timber stock. No splicing is inferred.");double rate=thicknessInches*widthInches/(12*.3048);return new TimberTakeoff{Kind=kind,Id=id,Length=length,Thickness=thicknessInches,Width=widthInches,StockFeet=stockFeet,Pieces=pieces,Demand=new SteelCutDemand{Member=kind+" "+id,Specification=specification.Trim().ToUpperInvariant()+" | "+thicknessInches.ToString("R",CultureInfo.InvariantCulture)+"x"+widthInches.ToString("R",CultureInfo.InvariantCulture),Length=length,Quantity=pieces,KgM=rate}};}
 public static Dictionary<TimberTakeoff,double> Purchase(IEnumerable<TimberTakeoff> source){var result=new Dictionary<TimberTakeoff,double>();foreach(var group in source.GroupBy(q=>q.StockFeet)){var stocks=SteelCutPlanner.Allocate(group.Select(q=>q.Demand),group.Key*.3048);foreach(var row in group)result[row]=SteelCutPlanner.PurchaseKg(stocks,row.Demand);}return result;}
}
partial class ProgramOfWorksForm {
 readonly List<TimberTakeoff> timberRows=new List<TimberTakeoff>();
 static readonly string[] CarpentryNames={"Modular Base Cabinets","Modular Wall Cabinets","Aluminum Cabinets","Roof Frame","Floor Frame","Fascia Board (12mm thk Fiber Cement Board)","Laminated Phenolic Board (Toilet and Urinal Partition)"};
 void AddCarpentryWorks(){for(int i=0;i<CarpentryNames.Length;i++){string key="Carpentry"+i,kind=CarpentryNames[i];if(i==3||i==4){var table=NewExtraGrid(key,kind,"Carpentry and Joinery Works",new[]{"Member ID","Description / location","Cut length m","Timber thickness in","Timber width in","Pieces","Commercial commercial length ft","Timber species / grade / treatment","NET bd.ft","BUY bd.ft","Status"},8,new Dictionary<int,string>{{3,"2"},{4,"3"},{5,"1"},{6,"12"},{7,"Project timber"}},"Board feet = thickness(in) × width(in) × length(ft) / 12 × pieces. Dimensions are the section used for estimating/billing. Compatible timber cuts share offcuts across Roof Frame and Floor Frame when specification, section and selected commercial length match. BOQ uses purchase board feet. No timber sizing, member capacity or splicing is designed.");ExtraChoice(table.Grid,6,"8","10","12","14","16","18","20","24");}
   else if(i==5)NewExtraGrid(key,kind,"Carpentry and Joinery Works",new[]{"Entry ID","Description / location","Measured run length m","Qty","Total fascia length m","Status"},4,new Dictionary<int,string>{{3,"1"}},"Fixed pay specification: 12mm-thick fiber-cement fascia board, measured in linear metres. Quantity = run length × repetitions. Roof/floor timber board feet do not include this item.");
   else NewExtraGrid(key,kind,"Carpentry and Joinery Works",new[]{"Entry ID","Description / location","Measured face length m","Measured face height m","Qty","Total deduction area m2","Pay quantity","Pay unit","Status"},6,new Dictionary<int,string>{{4,"1"},{5,"0"}},i==2?"Aluminum cabinets use EACH per the supplied BACKUP. Enter cabinet count; dimensions are optional reference only.":"Pay area = measured specified face length × height × quantity − total excluded area. Deductions are total for the row, not per unit. Base and wall cabinets have the same code but separate descriptions and target cells. This is pay-item measurement, not panel cutting or cabinet hardware design.");
  }}
 void RecalculateCarpentry(){timberRows.Clear();foreach(var item in extraGrids.Values.Where(t=>t.Group=="Carpentry and Joinery Works")){var ids=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(DataGridViewRow row in item.Grid.Rows){if(row.IsNewRow)continue;row.Tag=null;for(int c=item.Inputs;c<item.Grid.Columns.Count;c++)row.Cells[c].Value="";if(Empty(row))continue;try{RequireDescription(row);if(Cell(row,0)==""||!ids.Add(Cell(row,0)))throw new Exception("Enter a unique entry/member ID.");int index=int.Parse(item.Key.Substring("Carpentry".Length));if(index==3||index==4){var timber=TimberQuantities.Create(item.Kind,Cell(row,0),Cell(row,1),Number(row,2),Number(row,3),Number(row,4),Count(row,5),Number(row,6),Cell(row,7));timberRows.Add(timber);row.Tag=timber;row.Cells[8].Value=timber.Net;}
    else if(index==5){double length=Number(row,2);SteelWeight.Positive(length);double quantity=length*Count(row,3);row.Cells[4].Value=quantity;ExtraPayQuantity(item.Group,"1003(11)a1",item.Kind,quantity,"m",item.Kind+" "+Cell(row,0)+" | "+Cell(row,1),"Measured run × qty = "+Cell(row,2)+" × "+Cell(row,3));}
    else {bool each=index==2;double quantity;if(each)quantity=Count(row,4);else{quantity=SiteWorkTakeoff.Area(Number(row,2),Number(row,3),Count(row,4))-OptionalNumber(row,5);if(quantity<0||OptionalNumber(row,5)<0)throw new Exception("Deductions must be nonnegative and cannot exceed gross area.");}string code=index==0||index==1?"1003(3)":index==2?"1003(4)":"1003(14)",unit=each?"ea":"m2";row.Cells[6].Value=quantity;row.Cells[7].Value=unit;ExtraPayQuantity(item.Group,code,item.Kind,quantity,unit,item.Kind+" "+Cell(row,0)+" | "+Cell(row,1),each?"Entered cabinet count = "+Cell(row,4):"Measured face L × H × qty − total deduction = "+Cell(row,2)+" × "+Cell(row,3)+" × "+Cell(row,4)+" − "+Cell(row,5));}
    row.Cells[item.Grid.Columns.Count-1].Value="Estimated";
   }catch(Exception ex){row.Cells[item.Grid.Columns.Count-1].Value=ex.Message;errors.Add(item.Kind+" "+Cell(row,0)+": "+ex.Message);}}
  }
  try{var purchase=TimberQuantities.Purchase(timberRows);foreach(var row in timberRows){var grid=extraGrids[row.Kind=="Roof Frame"?"Carpentry3":"Carpentry4"].Grid;var target=grid.Rows.Cast<DataGridViewRow>().First(r=>object.ReferenceEquals(r.Tag,row));target.Cells[9].Value=purchase[row];ExtraPayQuantity("Carpentry and Joinery Works",row.Kind=="Roof Frame"?"1003(5)":"1003(6)",row.Kind,purchase[row],"bd.ft",row.Kind+" "+row.Id,"T(in) × W(in) × L(m)/0.3048 / 12 × pieces = "+row.Thickness+" × "+row.Width+" × "+row.Length+"/0.3048 / 12 × "+row.Pieces+"; stock "+row.StockFeet+"ft; "+row.Demand.Specification+"; net = "+row.Net.ToString("R",CultureInfo.InvariantCulture)+"bd.ft; purchase includes allocated unused stock; compatible cuts share stock without double-charging a timber piece");}}catch(Exception ex){errors.Add("Timber purchase: "+ex.Message);}
 }
}
}
